sites.find:
offset = 0;
int toggle = 0;
spawn = &spawns[entry_count];
entry_count += 10;
while (offset < 0x1860) {
    spawn[toggle].pos.x = (float)(0x338 - offset / 10);
    spawn[toggle].pos.y = 824.0f;
    spawn[toggle].set_spawn(
        (toggle & 1)
            ? SPAWN_ID_DEN_LIZARD_WEAK_SLOWER_0D
            : SPAWN_ID_DEN_ALIEN_BASIC_07,
        trigger_time_ms);
    spawn[toggle].count = 1;
    offset += 0x270;
    trigger_time_ms += 1500;
    ++toggle;
}

replacements.text:
offset = 0;
int toggle = 0;
spawn = &spawns[entry_count];
int *metadata = &spawn[0].template_id;
entry_count += 10;
while (offset < 0x1860) {
    spawn[toggle].pos.x = (float)(0x338 - offset / 10);
    spawn[toggle].pos.y = 824.0f;
    metadata[0] = (toggle & 1)
        ? SPAWN_ID_DEN_LIZARD_WEAK_SLOWER_0D
        : SPAWN_ID_DEN_ALIEN_BASIC_07;
    metadata[1] = trigger_time_ms;
    metadata[2] = 1;
    metadata += 6;
    offset += 0x270;
    trigger_time_ms += 1500;
    ++toggle;
}

offset = 0;
int toggle = 0;
spawn = &spawns[entry_count];
int *metadata = &spawn[0].template_id;
entry_count += 10;
while (offset < 0x1860) {
    quest_entry_original_t *entry =
        (quest_entry_original_t *)(metadata - 3);
    entry->pos.x = (float)(0x338 - offset / 10);
    entry->pos.y = 824.0f;
    metadata += 6;
    metadata[-6] = (toggle & 1)
        ? SPAWN_ID_DEN_LIZARD_WEAK_SLOWER_0D
        : SPAWN_ID_DEN_ALIEN_BASIC_07;
    metadata[-5] = trigger_time_ms;
    metadata[-4] = 1;
    offset += 0x270;
    trigger_time_ms += 1500;
    ++toggle;
}
